function leadMessage(lead, reminder) {
  if (reminder)
    return {
      subject: "Follow-up reminder: " + lead.name,
      body:
        "This hot lead has not been followed up.\n\nName: " +
        lead.name +
        "\nEmail: " +
        lead.email +
        "\nInterest level: " +
        lead.interest +
        "\n\nPlease follow up and update Followed Up? in Google Sheets.",
    };
  return {
    subject: "New lead received: " + lead.name,
    body: [
      "New lead received",
      "",
      "Name: " + lead.name,
      "Email: " + lead.email,
      "Phone: " + lead.phone,
      "Interest level: " + lead.interest,
      "Lead source: " + lead.source,
      "",
      "Notes: " + lead.notes,
    ].join("\n"),
  };
}

function slackLeadText(lead) {
  return leadMessage(lead, false).body.replace(
    /[&<>]/g,
    (character) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;" })[character],
  );
}

export default async ({ leads, settings }, context) => {
  for (const lead of leads) {
    const result = await context.actions.call("slack.post_message", {
      channelId: settings.channel,
      text: slackLeadText(lead),
      unfurlLinks: false,
      unfurlMedia: false,
    });
    if (result.channelId !== settings.channel || !result.ts)
      throw new Error("Slack did not confirm the message in the configured channel");
  }
  return { count: leads.length };
};

