function leadCell(value) {
  return ["string", "number", "boolean"].includes(typeof value) ? String(value).trim() : "";
}

function latestLeadContacts(leads) {
  return [...new Map(leads.map((lead) => [lead.email, lead])).values()];
}

function contactSearch(email) {
  return {
    filterGroups: [{ filters: [{ propertyName: "email", operator: "EQ", value: email }] }],
    properties: ["email"],
    limit: 2,
  };
}

function contactTarget(search, lead) {
  if (
    !Array.isArray(search?.results) ||
    search.results.length > 1 ||
    search.paging?.next ||
    search.paging?.nextAfter ||
    (search.total != null && search.total !== search.results.length)
  ) {
    throw new Error("HubSpot did not return a unique contact lookup by email");
  }
  const record = search.results[0];
  if (record === undefined) return null;
  if (
    record.archived === true ||
    !/^\d+$/.test(record.id ?? "") ||
    leadCell(record.properties?.email).toLowerCase() !== lead.email
  ) {
    throw new Error("HubSpot returned a contact for a different email");
  }
  return record.id;
}

function contactProperties(lead, settings) {
  const entries = {
    phone: lead.phone,
    message: lead.notes,
    [settings.sourceProperty]: lead.source,
    [settings.interestProperty]: lead.interest,
  };
  return Object.fromEntries(Object.entries(entries).filter(([, value]) => value));
}

function checkContact(record, lead, selectedId) {
  if (
    !record ||
    !/^\d+$/.test(record.id ?? "") ||
    (selectedId && selectedId !== record.id) ||
    leadCell(record.properties?.email).toLowerCase() !== lead.email
  ) {
    throw new Error("HubSpot did not confirm the expected contact");
  }
  return record.id;
}

export default async ({ leads, settings }, context) => {
  const writes = [];
  const contactIds = new Set();
  for (const lead of latestLeadContacts(leads)) {
    const search = await context.actions.call("hubspot.search_contacts", contactSearch(lead.email));
    const recordId = contactTarget(search, lead);
    if (recordId && contactIds.has(recordId))
      throw new Error("HubSpot matched two emails to the same contact ID");
    if (recordId) contactIds.add(recordId);
    writes.push({
      lead,
      recordId,
      properties: { email: lead.email, ...contactProperties(lead, settings) },
    });
  }
  for (const { lead, recordId, properties } of writes) {
    const result = recordId
      ? await context.actions.call("hubspot.update_contact", { recordId, properties })
      : await context.actions.call("hubspot.create_contact", { properties });
    checkContact(result.record, lead, recordId);
  }
  return { count: writes.length };
};

